const {
  AndroidConfig,
  withAndroidColors,
  withAndroidColorsNight,
  withAndroidStyles,
} = require('expo/config-plugins');

/**
 * The app's accent on Android's own dialogs.
 *
 * React Native's `Alert` is a native AppCompat `AlertDialog`, and its buttons are painted in the
 * activity theme's `colorAccent`. Expo's generated `AppTheme` sets no `colorAccent`, so AppCompat's
 * default — Material teal, `#009688` — was what «Закрити», «Скасувати» and every other dialog
 * button wore: the one colour on screen that belonged to no palette of this app (QA).
 *
 * `android/` is generated by `expo prebuild` and never hand-edited, so the colour goes in here:
 * one `colorAccent` resource per theme mode — `values/colors.xml` for light, `values-night/` for
 * dark, which `Theme.AppCompat.DayNight` resolves on its own as the system switches — and one
 * `<item name="colorAccent">` in `AppTheme` pointing at it. The dialog theme inherits it from
 * there; nothing else in this app reads `colorAccent`, since every React Native view is coloured
 * from `src/constants/theme.ts` directly.
 *
 * The two values are `Colors.light.accent` and `Colors.dark.accent` from that file, copied rather
 * than imported because a config plugin is plain Node and the theme is TypeScript.
 * `src/ui/android-accent.test.ts` fails the moment the two drift apart.
 */
const ACCENT = { light: '#9A6A12', dark: '#D9A441' };

/** The colour resource the theme item points at. */
const COLOR_NAME = 'colorAccent';

/** `colors.xml` (either mode) with the accent set, whatever was there before. */
function assignAccentColor(colors, value) {
  return AndroidConfig.Colors.assignColorValue(colors, { name: COLOR_NAME, value });
}

/** `styles.xml` with `AppTheme` taking its `colorAccent` from the resource above. */
function assignAccentStyle(styles) {
  return AndroidConfig.Styles.assignStylesValue(styles, {
    add: true,
    parent: AndroidConfig.Styles.getAppThemeGroup(),
    name: COLOR_NAME,
    value: `@color/${COLOR_NAME}`,
  });
}

function withAndroidAccent(config) {
  config = withAndroidColors(config, (mod) => {
    mod.modResults = assignAccentColor(mod.modResults, ACCENT.light);
    return mod;
  });
  config = withAndroidColorsNight(config, (mod) => {
    mod.modResults = assignAccentColor(mod.modResults, ACCENT.dark);
    return mod;
  });
  config = withAndroidStyles(config, (mod) => {
    mod.modResults = assignAccentStyle(mod.modResults);
    return mod;
  });
  return config;
}

module.exports = withAndroidAccent;
module.exports.ACCENT = ACCENT;
module.exports.assignAccentColor = assignAccentColor;
module.exports.assignAccentStyle = assignAccentStyle;
